update produccion.prisma_herramientas set modelos = '[{"id":"kling-3.0-turbo","etiqueta":"Kling 3.0 Turbo","rol":"rapido","como_llegar_es":"En Higgsfield: Video → Kling 3.0 en su modo rápido (Turbo) → pega el prompt.","como_llegar_en":"In Higgsfield: Video → Kling 3.0 in its fast (Turbo) mode → paste the prompt.","url":"https://higgsfield.ai/ai/video?model=kling3_0"},{"id":"kling-3.0","etiqueta":"Kling 3.0","rol":"fino","como_llegar_es":"En Higgsfield: Video → Kling 3.0 → pega el prompt (la foto va en Start frame).","como_llegar_en":"In Higgsfield: Video → Kling 3.0 → paste the prompt (the photo goes in Start frame).","url":"https://higgsfield.ai/ai/video?model=kling3_0"},{"id":"kling-3.0-motion-control","etiqueta":"Kling 3.0 Motion Control","rol":"fino","como_llegar_es":"En Higgsfield: Video → Motion Control → sube la foto del personaje y el video del movimiento; el prompt describe sólo el escenario y la luz.","como_llegar_en":"In Higgsfield: Video → Motion Control → upload the character photo and the motion video; the prompt only describes the setting and light.","url":"https://higgsfield.ai/ai/video/motion?model=kling-3-motion-control"}]'::jsonb, updated_at = now()
