update produccion.prisma_herramientas set modelos = '[{"id":"higgsfield","etiqueta":"Higgsfield DoP","rol":"fino","como_llegar_es":"En Higgsfield: Video → sube la foto → elige ese preset de cámara → pega el texto.","como_llegar_en":"In Higgsfield: Video → upload the photo → pick that camera preset → paste the text.","url":"https://higgsfield.ai/ai/video"}]'::jsonb, updated_at = now()
